import process from 'node:process'
import { sql } from 'drizzle-orm'
import { pgSchema, serial, timestamp, uuid } from 'drizzle-orm/pg-core'

const POSTGRES_SCHEMA = process.env.POSTGRES_SCHEMA as string

export const schema = pgSchema(POSTGRES_SCHEMA)

export function initEntity() {
  return {
    /**
     * Unique incremental id for each entity
     */
    _incrementalId: serial('_incremental_id').primaryKey(),
    /**
     * UUID for each entity, generated by the database
     */
    id: uuid('id')
      .unique()
      .notNull()
      .$defaultFn(() => sql`gen_random_uuid()`),
    /**
     * Timestamps for each entity when it was created
     */
    createdAt: timestamp('created_at')
      .notNull()
      .$onUpdateFn(() => sql`current_timestamp`),
    /**
     * Timestamps for each entity when it was last updated
     */
    updatedAt: timestamp('updated_at')
      .notNull()
      .$defaultFn(() => sql`current_timestamp`),
    /**
     * Timestamps for each entity when it was deleted.
     * The database uses soft delete to keep the data.
     */
    deletedAt: timestamp('deleted_at'),
  }
}
